// Superchat webhooks لا تبعث توقيع HMAC — نتحقق فقط من صحة البنية
// (event message_inbound موجود وmessage فيه content)
// الحماية الحقيقية: Superchat هو اللي بيعرف الـ webhook URL (secret endpoint)

const body = $json.body || {};
const event = body.event || '';
const msg = body.message || {};

const valid = (event === 'message_inbound' || event === '' ) &&
              (typeof body === 'object');

return [{ json: { signature_valid: valid, body: body } }];

// Superchat inbound webhook payload (direct from SuperChat):
// {"id":"pe_...","event":"message_inbound",
//  "message":{"id":"ms_...","status":"received","content":{"body":"Hello!","type":"text"},
//    "direction":"inbound","to":{"channel_id":"mc_..."},"from":{"id":"ct_...","identifier":"+20..."},
//    "conversation_id":"cv_..."}}
// Also accepts router-passed body (same structure) or
// router-extracted format (message_text / channel_patient_id on top level).

const body = $json.body || {};

const event = body.event || '';

if (event !== 'message_inbound') {
  return [{ json: { is_status_update: true, event: event, raw_body: body } }];
}

const msg = body.message || {};
const content = msg.content || {};
const from = msg.from || {};
const to = msg.to || {};

const channelPatientId = from.identifier || from.id || null;
const messageText = content.body || null;
const messageType = content.type || 'text';
const messageId = msg.id || null;
const channelId = to.channel_id || null;
const conversationId = msg.conversation_id || null;

const channelType = 'whatsapp';

const idempotencyKey = messageId ? `superchat_wa_${messageId}` : null;

if (!channelPatientId || !messageText) {
  return [{ json: { is_status_update: true, raw_body: body } }];
}

return [{
  json: {
    is_status_update: false,
    channel_patient_id: String(channelPatientId),
    patient_name: from.name || null,
    message_text: messageText,
    message_type: messageType,
    channel_code: 'whatsapp',
    superchat_channel_id: channelId,
    superchat_conversation_id: conversationId,
    message_id: messageId,
    idempotency_key: idempotencyKey,
    raw_body: body
  }
}];

const message = $('Parse SUPERCHAT Message').item.json;
const clinicLookup = $json;

return [{
  json: {
    ...message,
    clinic_id: clinicLookup.clinic_id || null,
    channel_id: clinicLookup.channel_id || null
  }
}];

const original = $('Merge Clinic With Message SUPERCHAT').item.json;
const secretResult = $json;

return [{
  json: {
    ...original,
    thikaa_api_token: secretResult.api_token || null,
    thikaa_signing_secret: secretResult.signing_secret || null,
    thikaa_tenant_identifier: secretResult.tenant_identifier || null,
    superchat_channel_id: secretResult.superchat_channel_id || original.superchat_channel_id || null
  }
}];

