const original = $('Merge Clinic With Message SUPERCHAT').item.json;
const patientResult = $json;

let patientId = null;
if (patientResult.data && patientResult.data.length > 0) {
    patientId = patientResult.data[0].patient_id;
} else if (patientResult.patient_id) {
    patientId = patientResult.patient_id;
} else if (patientResult[0] && patientResult[0].patient_id) {
    patientId = patientResult[0].patient_id;
}

if (!patientId) {
    console.error('No patient_id found:', JSON.stringify(patientResult));
    throw new Error('Failed to get patient_id from RPC response');
}

return [{
  json: {
    ...original,
    patient_id: patientId
  }
}];

const original = $('Merge Patient Data SUPERCHAT').item.json;
const convResult = $input.item.json;

// Response shape from Postgres RPC call:
// { "get_or_create_channel_conversation": { conversation_id, is_new, channel_id, channel_type, channel_conversation_id, status } }
let raw = convResult;
if (raw && raw.get_or_create_channel_conversation) {
  raw = raw.get_or_create_channel_conversation;
}

let conversationId = null;
let channelId = null;
if (raw && typeof raw === 'object') {
  conversationId = raw.conversation_id || (raw.result && raw.result.conversation_id) || null;
  channelId = raw.channel_id || (raw.result && raw.result.channel_id) || null;
}

if (!conversationId) {
  throw new Error('Failed to get conversation_id from RPC response: ' + JSON.stringify(convResult).slice(0, 200));
}

return [{
  json: {
    ...original,
    conversation_id: conversationId,
    channel_id: channelId,
    conversation_is_new: raw.is_new === true
  }
}];

const data = $input.item.json;

let replyText = data.reply_text ||
                data.response ||
                data.message ||
                data.answer ||
                data.body ||
                data.output ||
                data.result ||
                null;

if (!replyText || replyText.trim() === '') {
    replyText = 'عذراً، حصلت مشكلة في معالجة طلبك. حاول مرة أخرى 🙏';
}

if (replyText.length > 4000) {
    replyText = replyText.substring(0, 4000) + '...';
}

let patientId = data.channel_patient_id || data.to || data.recipient || null;

if (!patientId) {
    try {
        patientId = $('Parse SUPERCHAT Message').item.json.channel_patient_id || null;
    } catch (e) { console.log('Could not get from Parse'); }
}

return [{
    json: {
        ...data,
        thikaa_recipient: patientId,
        thikaa_message: replyText
    }
}];

