const payload = $('Prepare SUPERCHAT Reply').item.json;
const channelId = $('Merge Channel Secret SUPERCHAT').item.json.superchat_channel_id;
const contactResults = $('Find SuperChat Contact').item.json.results || [];
const target = $('Parse SUPERCHAT Message').item.json.channel_patient_id;

let contactId = null;
for (const c of contactResults) {
  for (const h of (c.handles || [])) {
    if (h.value === target) { contactId = c.id; break; }
  }
  if (contactId) break;
}

// Fallback: SuperChat replies are only possible when a contact with a matching
// channel handle exists (created after the user's first inbound message).
// Without such a contact we cannot send a reply; record the best effort.
if (!contactId) {
  contactId = (contactResults[0] || {}).id || null;
}

return [{ json: { ...payload, superchat_contact_id: contactId, superchat_reply_possible: !!contactId } }];

const crypto = require('crypto');
const src = $('Merge Conversation Data SUPERCHAT').item.json || {};
const secretRow = $('Merge Channel Secret SUPERCHAT').item.json || {};
const core_payload = { clinic_id: src.clinic_id || null, channel_type: 'whatsapp', channel_provider: src.channel_provider || 'superchat', channel_id: src.channel_id || null, patient_id: src.patient_id || null, conversation_id: src.conversation_id || null, message_text: src.message_text || '', message_id: src.message_id || null, event_id: src.idempotency_key || src.event_id || null };
const secret = String(secretRow.thikaa_signing_secret || secretRow.signing_secret || '');
const signature = secret ? crypto.createHmac('sha256', secret).update(JSON.stringify(core_payload)).digest('hex') : null;
return [{ json: { ...src, core_payload, k2_signature: signature } }];

